import type { CSSProperties } from 'react';

/**
 * Photo-specific framing for circular avatars.
 *
 * Prefer object-position instead of cropping or upscaling original assets.
 * Keep the default centre framing for all unlisted images.
 * Keys deliberately omit file extensions so the same rule applies to JPEG
 * and the WebP version generated by optimize:images.
 */
const AVATAR_IMAGE_POSITIONS: Readonly<Record<string, CSSProperties['objectPosition']>> = {
  '/assets/seasons/2026-27/staff/southboys-chen-mei-ling-excel.': '50% 0%',
};

export const getAvatarImagePosition = (src?: string): CSSProperties['objectPosition'] => {
  if (!src) return '50% 50%';
  const entry = Object.entries(AVATAR_IMAGE_POSITIONS).find(([path]) => src.includes(path));
  return entry?.[1] ?? '50% 50%';
};
